// Agrupa los 170 archivos del Drive en pares (xml + pdf) por folio.
// Clave primaria: nombre sin extensión. Fallback: última secuencia numérica del nombre.
const files = ($input.first().json.files) || [];
const clean = (s) => (s === null || s === undefined ? '' : String(s)).trim();
const stripExt = (s) => clean(s).replace(/\.[^.]+$/, '');
const keyOf = (s) => stripExt(s).toLowerCase().replace(/[\s_]+/g, ' ').trim();
const numKey = (s) => {
  const m = stripExt(s).match(/[A-Za-z]*\d{2,}/g);
  return m ? m[m.length - 1].toLowerCase() : null;
};

const grupos = new Map();
const push = (key, f, ext) => {
  if (!grupos.has(key)) {
    grupos.set(key, { folio: key, xml_file_id: null, xml_name: null, pdf_file_id: null, pdf_name: null });
  }
  const g = grupos.get(key);
  if (ext === 'xml') { g.xml_file_id = f.id; g.xml_name = clean(f.name); }
  else { g.pdf_file_id = f.id; g.pdf_name = clean(f.name); }
};

const archivos = files
  .map((f) => ({ f, ext: (clean(f.name).split('.').pop() || '').toLowerCase() }))
  .filter((x) => x.ext === 'xml' || x.ext === 'pdf');

for (const { f, ext } of archivos) push(keyOf(f.name), f, ext);

// Segunda pasada: reintenta emparejar huérfanos cuyo pdf y xml se llaman distinto.
const huerfanos = [...grupos.values()].filter((g) => !g.xml_file_id || !g.pdf_file_id);
if (huerfanos.length > 1) {
  const porNum = new Map();
  for (const g of huerfanos) {
    const n = numKey(g.xml_name || g.pdf_name || g.folio);
    if (!n) continue;
    if (!porNum.has(n)) porNum.set(n, []);
    porNum.get(n).push(g);
  }
  for (const [, lista] of porNum) {
    if (lista.length < 2) continue;
    const conXml = lista.find((g) => g.xml_file_id);
    const conPdf = lista.find((g) => g.pdf_file_id && !g.xml_file_id);
    if (!conXml || !conPdf || conXml === conPdf) continue;
    conXml.pdf_file_id = conPdf.pdf_file_id;
    conXml.pdf_name = conPdf.pdf_name;
    grupos.delete(conPdf.folio);
  }
}

return [...grupos.values()].map((g) => ({ json: g }));

// Busca en TODO el XML del CFDI la descripción del concepto y extrae proyecto + depa.
// Formatos reales vistos:
//   "40101700 - Condensadora departamento 1307 bottura"
//   "Primer pago condensadora departamento Gala 913 Bottura"  <- modelo antes del número
//   "Primer pago condensadora departamento Modena 913"        <- solo el modelo, sin proyecto
// El proyecto se resuelve por nombre (mapa_producto_por_proyecto) o por el modelo
// (alias_modelo_a_proyecto: gala/modena -> bottura).
const ctx = $('Solo folios con XML').item.json;
const cfg = $('Configuración').first().json;
const xml = $input.item.json;

const norm = (s) => String(s).normalize('NFD').replace(new RegExp('\\p{M}', 'gu'), '').toLowerCase();

const mapa = cfg.mapa_producto_por_proyecto || {};
const proyectosConocidos = Object.keys(mapa).map(norm);

// Modelos que identifican un proyecto (ej. Gala y Modena son modelos de Bottura).
const aliasCfg = cfg.alias_modelo_a_proyecto || {};
const alias = {};
for (const [modelo, proy] of Object.entries(aliasCfg)) alias[norm(modelo)] = norm(proy);

const textos = [];
(function walk(n) {
  if (n === null || n === undefined) return;
  if (typeof n === 'string') { textos.push(n); return; }
  if (typeof n === 'number' || typeof n === 'boolean') return;
  if (Array.isArray(n)) { n.forEach(walk); return; }
  if (typeof n === 'object') { Object.values(n).forEach(walk); }
})(xml);

function parsear(desc) {
  const n = norm(desc);
  const pos = n.indexOf('condensadora');
  let cola = pos >= 0 ? n.slice(pos + 'condensadora'.length) : n;
  // Quita "departamento" / "depto" / "depa" y sus preposiciones, si aparecen.
  cola = cola.replace(/^[\s\-–:,]*(?:de\s+la\s+|de\s+el\s+|del\s+|de\s+)?(?:departamentos?|deptos?\.?|dptos?\.?|depas?|deps?\.?)\b/, ' ');
  const tokens = cola.split(/[\s,;:.\-–_/()]+/).filter(Boolean);
  const conDigitos = (t) => /\d/.test(t);

  // 1) Proyecto por nombre explícito (bottura, ...), buscando desde el final.
  let proyecto = null;
  let idxProy = -1;
  for (let i = tokens.length - 1; i >= 0; i--) {
    if (proyectosConocidos.includes(tokens[i])) { proyecto = tokens[i]; idxProy = i; break; }
  }

  // 2) Modelo conocido (gala, modena, ...) -> proyecto. Sirve tanto para resolver el
  //    proyecto cuando no viene escrito, como para ubicar el número que va después.
  let idxModelo = -1;
  for (let i = 0; i < tokens.length; i++) {
    if (alias[tokens[i]] !== undefined) { idxModelo = i; if (!proyecto) proyecto = alias[tokens[i]]; break; }
  }

  // 3) Último recurso: el último token alfabético.
  if (!proyecto) {
    for (let i = tokens.length - 1; i >= 0; i--) {
      if (/^[a-z]{3,}$/.test(tokens[i])) { proyecto = tokens[i]; idxProy = i; break; }
    }
  }

  // Número de departamento:
  //   a) si hay modelo, el primer token con dígitos después del modelo ("gala 913");
  //   b) si no, el último token con dígitos antes del nombre del proyecto ("1307 bottura");
  //   c) si no, el primero con dígitos.
  let num = null;
  if (idxModelo >= 0) {
    for (let i = idxModelo + 1; i < tokens.length; i++) {
      if (conDigitos(tokens[i]) && i !== idxProy) { num = tokens[i]; break; }
    }
  }
  if (!num && idxProy >= 0) {
    for (let i = idxProy - 1; i >= 0; i--) {
      if (conDigitos(tokens[i])) { num = tokens[i]; break; }
    }
  }
  if (!num) {
    for (let i = 0; i < tokens.length; i++) {
      if (conDigitos(tokens[i]) && i !== idxProy) { num = tokens[i]; break; }
    }
  }
  if (num) num = num.replace(/^#+/, '').toUpperCase();

  const modelo = idxModelo >= 0 ? tokens[idxModelo] : null;
  return { proyecto, num_depa: num, modelo };
}

// Candidatas: cualquier texto que hable de condensadora (o, en su defecto, de departamento).
const candidatas = textos.filter((t) => /condensadora/i.test(norm(t)));
const respaldo = candidatas.length ? candidatas : textos.filter((t) => /departamento|depto|depa\b/i.test(norm(t)));

let elegida = null;
let parseo = { proyecto: null, num_depa: null, modelo: null };
// Prefiere la descripción cuyo proyecto sea conocido y que traiga número.
for (const t of respaldo) {
  const p = parsear(t);
  const buena = p.num_depa && p.proyecto && proyectosConocidos.includes(p.proyecto);
  if (buena) { elegida = t; parseo = p; break; }
  if (!elegida && (p.num_depa || p.proyecto)) { elegida = t; parseo = p; }
}

// Folio fiscal (UUID) para el log.
let uuid = null;
for (const t of textos) {
  const r = String(t).match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
  if (r) { uuid = r[0].toUpperCase(); break; }
}

const num_depa = parseo.num_depa || null;
const proyecto = parseo.proyecto || null;
const id_producto = proyecto && mapa[proyecto] !== undefined ? mapa[proyecto] : null;

return {
  json: {
    ...ctx,
    descripcion: elegida ? String(elegida).trim() : null,
    descripciones_candidatas: respaldo.slice(0, 5).map((t) => String(t).trim()),
    uuid,
    modelo: parseo.modelo || null,
    num_depa,
    proyecto,
    id_producto,
    // Valores neutros para que la consulta SQL nunca reciba null.
    q_num_depa: num_depa || '',
    q_id_producto: id_producto === null ? 0 : id_producto,
    error_parseo: num_depa && proyecto ? null : 'no_se_pudo_parsear_descripcion',
    error_proyecto: proyecto && id_producto === null ? 'proyecto_sin_id_producto_mapeado' : null
  }
};

// Decide, por cuenta, qué documentos faltan. Emite 1 item por documento a subir
// y 1 item "omitir" cuando no hay nada que hacer (para que el log salga completo).
const cfg = $('Configuración').first().json;
const ctxItems = $('Extraer proyecto y depa').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  let ctx;
  try { ctx = $('Extraer proyecto y depa').itemMatching(i).json; }
  catch (e) { ctx = (ctxItems[i] || { json: {} }).json; }

  const base = {
    folio: ctx.folio || null,
    proyecto: ctx.proyecto || null,
    num_depa: ctx.num_depa || null,
    uuid: ctx.uuid || null,
    descripcion: ctx.descripcion || null,
    xml_file_id: ctx.xml_file_id || null,
    xml_name: ctx.xml_name || null,
    pdf_file_id: ctx.pdf_file_id || null,
    pdf_name: ctx.pdf_name || null,
    id_cuenta_cobranza: r.id_cuenta_cobranza || null,
    tiene_xml: r.tiene_xml === true,
    tiene_pdf: r.tiene_pdf === true,
    n_coincidencias: r.n_coincidencias || 0
  };

  if (!ctx.num_depa || !ctx.proyecto) {
    out.push({ json: { ...base, accion: 'omitir', motivo: 'no_se_pudo_parsear_descripcion' } });
    continue;
  }
  if (ctx.id_producto === null || ctx.id_producto === undefined) {
    out.push({ json: { ...base, accion: 'omitir', motivo: 'proyecto_sin_id_producto_mapeado' } });
    continue;
  }
  if (!base.id_cuenta_cobranza) {
    out.push({ json: { ...base, accion: 'omitir', motivo: 'sin_cuenta_de_cobranza' } });
    continue;
  }
  if (base.n_coincidencias > 1) {
    // Seguridad: no adivinar. Si hay varias cuentas activas para el mismo depa, se reporta.
    out.push({ json: { ...base, accion: 'omitir', motivo: 'cuenta_ambigua_' + base.n_coincidencias + '_coincidencias' } });
    continue;
  }

  const faltantes = [];
  if (!base.tiene_xml && base.xml_file_id) {
    faltantes.push({ tipo: 'xml', id_tipo_documento: cfg.id_tipo_documento_xml, file_id: base.xml_file_id, file_name: base.xml_name });
  }
  if (!base.tiene_pdf && base.pdf_file_id) {
    faltantes.push({ tipo: 'pdf', id_tipo_documento: cfg.id_tipo_documento_pdf, file_id: base.pdf_file_id, file_name: base.pdf_name });
  }

  if (faltantes.length === 0) {
    const motivo = base.tiene_xml && base.tiene_pdf
      ? 'ya_tenia_ambos'
      : 'falta_documento_pero_no_hay_archivo_en_drive';
    out.push({ json: { ...base, accion: 'omitir', motivo } });
    continue;
  }

  for (const f of faltantes) {
    out.push({ json: { ...base, accion: 'subir', motivo: null, ...f } });
  }
}

return out;

// Construye la URL pública del archivo de Drive.
// XML -> descarga directa (la app necesita el contenido). PDF -> visor de Drive.
const ctx = $('Hay que subir').item.json;
const permiso = $input.item.json || {};
const compartido = !!permiso.id && !permiso.error;

const url = ctx.tipo === 'xml'
  ? 'https://drive.google.com/uc?export=download&id=' + ctx.file_id
  : 'https://drive.google.com/file/d/' + ctx.file_id + '/view';

return { json: { ...ctx, url_publica: url, permiso_publico_ok: compartido } };

