// Log final: una línea por cuenta con cuenta_cobranza,pdf,xml (si/no = subido en esta corrida).
const plan = $('Planear cargas').all().map((i) => i.json);
const pares = $('Emparejar por folio').all().map((i) => i.json);

let insertados = [];
try {
  insertados = $('Insertar documento').all().map((i) => i.json);
} catch (e) {
  insertados = [];
}
let urls = [];
try {
  urls = $('Construir URL pública').all().map((i) => i.json);
} catch (e) {
  urls = [];
}

// Cuáles inserciones realmente quedaron (la fila devuelta trae id).
const okPorCuentaTipo = new Set();
for (const r of insertados) {
  if (r && r.id && r.id_cuenta_cobranza) okPorCuentaTipo.add(r.id_cuenta_cobranza + ':' + r.id_tipo_documento);
}

// Agrupa el plan por cuenta (o por folio cuando no hubo cuenta).
const porClave = new Map();
for (const p of plan) {
  const clave = p.id_cuenta_cobranza ? 'cc:' + p.id_cuenta_cobranza : 'folio:' + p.folio;
  if (!porClave.has(clave)) {
    porClave.set(clave, {
      id_cuenta_cobranza: p.id_cuenta_cobranza,
      folio: p.folio,
      proyecto: p.proyecto,
      num_depa: p.num_depa,
      xml_subido: false,
      pdf_subido: false,
      tenia_xml: p.tiene_xml,
      tenia_pdf: p.tiene_pdf,
      motivos: new Set()
    });
  }
  const g = porClave.get(clave);
  if (p.motivo) g.motivos.add(p.motivo);
  if (p.accion === 'subir' && p.id_cuenta_cobranza) {
    const ok = okPorCuentaTipo.has(p.id_cuenta_cobranza + ':' + p.id_tipo_documento);
    if (p.tipo === 'xml') g.xml_subido = g.xml_subido || ok;
    if (p.tipo === 'pdf') g.pdf_subido = g.pdf_subido || ok;
    if (!ok) g.motivos.add('fallo_insert_' + p.tipo);
  }
}

const huerfanos = pares.filter((p) => !p.xml_file_id || !p.pdf_file_id);
const filas = [...porClave.values()].sort((a, b) => (a.id_cuenta_cobranza || 0) - (b.id_cuenta_cobranza || 0));
const si = (b) => (b ? 'si' : 'no');

const L = [];
L.push('# Carga de facturas de condensadoras -> tabla documentos');
L.push('# Ejecutado: ' + $now.toISO());
const totalArchivos = pares.reduce((n, p) => n + (p.xml_file_id ? 1 : 0) + (p.pdf_file_id ? 1 : 0), 0);
L.push('# Archivos en Drive: ' + totalArchivos + ' | folios detectados: ' + pares.length);
L.push('# Cuentas procesadas: ' + filas.length);
L.push('');
L.push('cuenta_cobranza,pdf,xml');
for (const f of filas) {
  L.push((f.id_cuenta_cobranza || 'SIN_CUENTA') + ',' + si(f.pdf_subido) + ',' + si(f.xml_subido));
}
L.push('');
L.push('# --- detalle ---');
L.push('# folio | proyecto | depa | cuenta | pdf_subido | xml_subido | ya_tenia_pdf | ya_tenia_xml | motivo');
for (const f of filas) {
  L.push([
    f.folio || '',
    f.proyecto || '',
    f.num_depa || '',
    f.id_cuenta_cobranza || 'SIN_CUENTA',
    si(f.pdf_subido),
    si(f.xml_subido),
    si(f.tenia_pdf),
    si(f.tenia_xml),
    [...f.motivos].join(';') || '-'
  ].join(' | '));
}
if (huerfanos.length) {
  L.push('');
  L.push('# --- folios sin par completo en Drive ---');
  for (const h of huerfanos) {
    L.push(h.folio + ' | xml: ' + (h.xml_name || 'FALTA') + ' | pdf: ' + (h.pdf_name || 'FALTA'));
  }
}
L.push('');
L.push('# Documentos insertados en esta corrida: ' + insertados.filter((r) => r && r.id).length);

return [{
  json: {
    log_txt: L.join('\n'),
    cuentas: filas.length,
    insertados: insertados.filter((r) => r && r.id).length,
    urls_generadas: urls.length
  }
}];
